(function(){
'use strict';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let loading=false,saving=false,realtimeChannel=null,refreshTimer=null,allowOpen=false,modalObserver=null,installed=false;
const db=()=>window.VolleySupabase?.getClient?.()||null;
const st=()=>typeof appState!=='undefined'?appState:null;
const call=(name,...args)=>{try{if(typeof window[name]==='function')return window[name](...args);}catch(e){console.warn('[AttendanceAuthoritative]',name,e);}};
function localPlayerByAny(id,username){const s=st();if(!s)return null;const sid=String(id??''),u=String(username??'').toLowerCase();return(s.players||[]).find(p=>[p.id,p.supabaseId,p.legacy_id,p.legacyId,p.profile_id,p.authId].filter(Boolean).map(String).includes(sid)||(u&&String(p.username||'').toLowerCase()===u))||null;}
function localEventByAny(id){const s=st();if(!s)return null;const sid=String(id??'');return(s.events||[]).find(e=>[e.id,e.supabaseId,e.supabase_id,e.legacy_id,e.legacyId].filter(Boolean).map(String).includes(sid))||null;}
async function resolveEventUuid(id){const c=db();if(!c||!id)return null;const sid=String(id);if(UUID.test(sid)){const{data}=await c.from('events').select('id').eq('id',sid).maybeSingle();if(data?.id)return data.id;}const ev=localEventByAny(id),direct=ev?.supabaseId||ev?.supabase_id;if(direct&&UUID.test(String(direct)))return String(direct);const legacy=ev?.legacy_id||ev?.legacyId||(!UUID.test(sid)?sid:null);if(!legacy)return null;const{data,error}=await c.from('events').select('id').eq('legacy_id',String(legacy)).maybeSingle();if(error)throw error;return data?.id||null;}
async function syncMappings(){const c=db(),s=st();if(!c||!s)return;const{data,error}=await c.from('players').select('id,legacy_id,profile_id,active,profiles:profile_id(username,full_name)');if(error)throw error;for(const row of data||[]){if(row.active===false)continue;const p=localPlayerByAny(row.id,row.profiles?.username)||localPlayerByAny(row.legacy_id,row.profiles?.username);if(!p)continue;p.supabaseId=row.id;if(row.legacy_id){p.legacy_id=row.legacy_id;p.legacyId=p.legacyId||row.legacy_id;}if(row.profile_id)p.profile_id=row.profile_id;}}
function snapshot(s){return JSON.stringify({c:(s.trainingConfirmations||[]).map(x=>[x.eventId,x.playerId,x.status]).sort(),a:(s.attendanceData||[]).map(x=>[x.eventId,x.playerId,x.status]).sort()});}
async function loadAttendance(opts={}){if(loading)return;const c=db(),s=st();if(!c||!s)return;loading=true;try{const before=snapshot(s);await syncMappings();const{data,error}=await c.from('attendance').select('id,event_id,player_id,player_response,official_status,validated_at,created_at,updated_at');if(error)throw error;const conf=[],official=[];for(const row of data||[]){const p=localPlayerByAny(row.player_id),ev=localEventByAny(row.event_id);if(!p||!ev)continue;if(['yes','no'].includes(row.player_response))conf.push({id:row.id,eventId:ev.id,eventIdLegacy:ev.legacy_id||ev.legacyId||null,playerId:p.id,playerIdLegacy:p.legacy_id||p.legacyId||null,status:row.player_response,timestamp:row.updated_at||row.created_at,supabaseEventId:row.event_id,supabasePlayerId:row.player_id});if(row.official_status)official.push({id:row.id,eventId:ev.id,eventIdLegacy:ev.legacy_id||ev.legacyId||null,playerId:p.id,playerIdLegacy:p.legacy_id||p.legacyId||null,playerName:p.name||p.username||'Jugadora',status:row.official_status,source:'supabase',validatedAt:row.validated_at||row.updated_at||row.created_at,supabaseEventId:row.event_id,supabasePlayerId:row.player_id});}s.trainingConfirmations=conf;s.attendanceData=official;try{if(typeof saveAppData==='function')saveAppData(s);}catch(_){}document.documentElement.classList.add('attendance-ready');if(before!==snapshot(s)&&!opts.silent){call('renderHomeDashboard');call('renderHomePortalRSVP');call('renderTraining');call('renderCoachAttendanceList');try{if(typeof activeSessionId!=='undefined'&&activeSessionId)call('renderSessionCenterDetail');}catch(_){}}return{confirmations:conf,official};}catch(e){console.error('[AttendanceAuthoritative] load',e);throw e;}finally{loading=false;}}
async function confirmAttendance(eventId,status,btn){if(!['yes','no'].includes(status))return;const c=db();if(!c)return;if(btn){btn.disabled=true;btn.dataset.originalText=btn.innerHTML;}try{const eid=await resolveEventUuid(eventId);if(!eid)throw new Error('No se encuentra este entrenamiento en Supabase.');const ident=await window.VolleySupabase?.getIdentity?.(),pid=ident?.data?.player?.id;if(!UUID.test(String(pid||'')))throw new Error('No se encuentra la ficha Supabase de la jugadora.');const now=new Date().toISOString();const{error}=await c.from('attendance').upsert({event_id:eid,player_id:pid,player_response:status,updated_at:now},{onConflict:'event_id,player_id'});if(error)throw error;await loadAttendance({silent:true});call('renderHomeDashboard');call('renderHomePortalRSVP');call('renderTraining');if(typeof showToast==='function')showToast(status==='yes'?'Asistencia confirmada.':'Ausencia comunicada.');}catch(e){console.error('[AttendanceAuthoritative] confirm',e);if(typeof showToast==='function')showToast('Error al guardar en Supabase: '+(e.message||e),'error');}finally{if(btn){btn.disabled=false;if(btn.dataset.originalText)btn.innerHTML=btn.dataset.originalText;}}}
function closeRollCall(){allowOpen=false;document.getElementById('modal-verify-attendance')?.classList.remove('active');}
function statusClass(v){return v?`is-${v}`:'is-empty';}
function matchesEvent(x,ev,eventId){const ids=[ev?.id,ev?.legacy_id,ev?.legacyId,ev?.supabaseId,ev?.supabase_id,eventId].filter(Boolean).map(String);return ids.includes(String(x.eventId??''))||ids.includes(String(x.eventIdLegacy??''))||ids.includes(String(x.supabaseEventId??''));}
function matchesPlayer(x,p){const ids=[p.id,p.legacy_id,p.legacyId,p.supabaseId,p.profile_id].filter(Boolean).map(String);return ids.includes(String(x.playerId??''))||ids.includes(String(x.playerIdLegacy??''))||ids.includes(String(x.supabasePlayerId??''));}
function bindDirectSave(){const form=document.getElementById('form-verify-attendance');if(!form)return;const btn=form.querySelector('button[type="submit"],button[data-rollcall-save],.btn-primary');if(!btn)return;btn.type='button';btn.dataset.rollcallSave='1';btn.onclick=event=>{event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();void saveRollCallDirect(form);};}
function drawRollCall(eventId){const s=st(),modal=document.getElementById('modal-verify-attendance'),container=document.getElementById('verify-attendance-list-container'),hidden=document.getElementById('verify-attendance-event-id');if(!s||!modal||!container||!hidden)return;const ev=localEventByAny(eventId);hidden.value=ev?.id||eventId;const title=document.getElementById('verify-attendance-title');if(title&&ev)title.innerHTML=`<i data-lucide="clipboard-check"></i> Pasar Lista: ${ev.title||'Entrenamiento'} (${ev.date||''})`;container.innerHTML='';for(const p of s.players||[]){if(p.active===false)continue;const rsvp=(s.trainingConfirmations||[]).find(x=>matchesEvent(x,ev,eventId)&&matchesPlayer(x,p));const log=(s.attendanceData||[]).find(x=>matchesEvent(x,ev,eventId)&&matchesPlayer(x,p));const current=log?.status||'',remote=String(p.supabaseId||'');const tag=rsvp?.status==='yes'?'<span class="rsvp-tag-yes">✓ Dijo que Sí</span>':rsvp?.status==='no'?'<span class="rsvp-tag-no">✗ Dijo que No</span>':'<span class="rsvp-tag-none">Sin responder</span>';const row=document.createElement('div');row.className='verify-attendance-item status-row';row.innerHTML=`<div class="roll-call-player"><strong>#${p.number??p.dorsal??''} ${p.name||p.username||'Jugadora'}</strong><small>${tag}</small></div><select id="verify-status-${p.id}" data-player-uuid="${remote}" class="roll-call-status-select ${statusClass(current)}"><option value="" ${!current?'selected':''}>Sin validar</option><option value="present" ${current==='present'?'selected':''}>Presente</option><option value="late" ${current==='late'?'selected':''}>Tarde</option><option value="justified" ${current==='justified'?'selected':''}>Justificada</option><option value="unjustified" ${current==='unjustified'?'selected':''}>No justificada</option></select>`;const sel=row.querySelector('select');sel?.addEventListener('change',()=>sel.className=`roll-call-status-select ${statusClass(sel.value)}`);container.appendChild(row);}bindDirectSave();if(allowOpen)modal.classList.add('active');try{window.lucide?.createIcons?.();}catch(_){}}
async function openRollCall(eventId){allowOpen=true;try{await loadAttendance({silent:true});}catch(_){}if(!allowOpen)return;drawRollCall(eventId);}
async function saveRollCallDirect(form){if(saving)return;saving=true;const btn=form?.querySelector('button[data-rollcall-save],button[type="button"].btn-primary'),original=btn?.innerHTML;if(btn){btn.disabled=true;btn.textContent='Guardando…';}try{const c=db();if(!c)throw new Error('Supabase no está disponible.');const eid=await resolveEventUuid(document.getElementById('verify-attendance-event-id')?.value);if(!UUID.test(String(eid||'')))throw new Error('No se encuentra el entrenamiento en Supabase.');const identity=await window.VolleySupabase?.getIdentity?.();const profileId=identity?.data?.profile?.id;const coachId=UUID.test(String(profileId||''))?profileId:null;const now=new Date().toISOString(),rows=[],clearIds=[],counts={present:0,late:0,justified:0,unjustified:0};const selects=[...document.querySelectorAll('#verify-attendance-list-container .roll-call-status-select')];if(!selects.length)throw new Error('No se han encontrado jugadoras en la lista.');for(const sel of selects){const pid=String(sel.dataset.playerUuid||'');if(!UUID.test(pid))throw new Error('Hay una jugadora sin vínculo válido con Supabase. Recarga la página e inténtalo de nuevo.');const status=String(sel.value||'');if(['present','late','justified','unjustified'].includes(status)){counts[status]++;rows.push({event_id:eid,player_id:pid,official_status:status,validated_by:coachId,validated_at:now,updated_at:now});}else clearIds.push(pid);}if(rows.length){const{data,error}=await c.from('attendance').upsert(rows,{onConflict:'event_id,player_id'}).select('id,event_id,player_id,official_status');if(error)throw error;if((data||[]).length!==rows.length)throw new Error(`Supabase solo confirmó ${(data||[]).length} de ${rows.length} estados.`);}if(clearIds.length){const{error}=await c.from('attendance').update({official_status:null,validated_by:null,validated_at:null,updated_at:now}).eq('event_id',eid).in('player_id',clearIds);if(error)throw error;}const{data:verified,error:verifyError}=await c.from('attendance').select('player_id,official_status').eq('event_id',eid).not('official_status','is',null);if(verifyError)throw verifyError;const expected=new Map(rows.map(r=>[r.player_id,r.official_status]));for(const [pid,status] of expected){const got=(verified||[]).find(v=>String(v.player_id)===pid)?.official_status;if(got!==status)throw new Error('La lista no se confirmó correctamente en Supabase.');}await loadAttendance({silent:true});closeRollCall();call('renderTraining');call('renderCoachAttendanceList');call('renderHomeDashboard');if(typeof showToast==='function')showToast(`Lista guardada · ${counts.present} presentes · ${counts.late} tarde · ${counts.justified} justificadas · ${counts.unjustified} no justificadas.`);}catch(e){console.error('[AttendanceAuthoritative] roll call',e);if(typeof showToast==='function')showToast(e.message||'No se pudo guardar la lista.','error');}finally{saving=false;if(btn){btn.disabled=false;btn.innerHTML=original||'Confirmar Lista';}}}
function installModalGuard(){const modal=document.getElementById('modal-verify-attendance');if(!modal||modalObserver)return;modalObserver=new MutationObserver(()=>{if(modal.classList.contains('active')&&!allowOpen)modal.classList.remove('active');});modalObserver.observe(modal,{attributes:true,attributeFilter:['class']});}
document.addEventListener('click',event=>{const modal=document.getElementById('modal-verify-attendance');if(!modal)return;const button=event.target?.closest?.('button'),text=String(button?.textContent||'').trim().toLowerCase();if((button&&modal.contains(button)&&(text.includes('cancelar')||button.classList.contains('modal-close')||button.dataset?.dismiss==='modal'))||event.target===modal){event.preventDefault();event.stopImmediatePropagation();closeRollCall();}},true);
function subscribe(){const c=db();if(!c||realtimeChannel)return;realtimeChannel=c.channel('attendance-authoritative-live').on('postgres_changes',{event:'*',schema:'public',table:'attendance'},()=>void loadAttendance({silent:false})).subscribe();}
function injectCss(){if(document.getElementById('attendance-authoritative-css'))return;const style=document.createElement('style');style.id='attendance-authoritative-css';style.textContent=`button[onclick*="openVerifyAttendanceModal"]{position:relative!important;z-index:2!important;pointer-events:auto!important}button[onclick*="openVerifyAttendanceModal"] *{pointer-events:none!important}.verify-attendance-item.status-row{display:grid!important;grid-template-columns:minmax(170px,1fr) minmax(180px,230px);gap:1rem;align-items:center;padding:.8rem 0}.roll-call-player{display:flex;flex-direction:column;gap:.25rem}.roll-call-status-select{width:100%;padding:.6rem .7rem;border:1px solid #cbd5e1;border-radius:10px;background:#fff;font-weight:700;color:#0f172a}.roll-call-status-select.is-present{border-color:#86efac;background:#f0fdf4}.roll-call-status-select.is-late{border-color:#fde68a;background:#fffbeb}.roll-call-status-select.is-justified{border-color:#93c5fd;background:#eff6ff}.roll-call-status-select.is-unjustified{border-color:#fca5a5;background:#fef2f2}@media(max-width:640px){.verify-attendance-item.status-row{grid-template-columns:1fr}.roll-call-status-select{font-size:16px}}`;document.head.appendChild(style);}
function install(){if(installed)return;installed=true;const wait=()=>{if(!window.VolleySupabase||typeof window.openVerifyAttendanceModal!=='function'){setTimeout(wait,150);return;}window.loadAttendanceFromSupabase=loadAttendance;window.confirmTrainingAttendance=confirmAttendance;window.openVerifyAttendanceModal=openRollCall;window.forceCloseRollCallAuthoritative=closeRollCall;window.saveRollCallAuthoritative=()=>saveRollCallDirect(document.getElementById('form-verify-attendance'));installModalGuard();injectCss();subscribe();void loadAttendance({silent:false});if(refreshTimer)clearInterval(refreshTimer);refreshTimer=setInterval(()=>void loadAttendance({silent:false}),5000);console.info('[AttendanceAuthoritative] Guardar lista usa botón directo; el submit antiguo queda fuera del flujo.');};setTimeout(wait,1200);}
install();
})();